def elevator_door_floor(commands, min_floor, max_floor):
    current_floor = min_floor
    door_state = "CLOSED"
    for command in commands:
        if command == "open":
            door_state = "OPEN"
        elif command == "close":
            door_state = "CLOSED"
        elif command == "up" and door_state == "CLOSED":
            if current_floor < max_floor:
                current_floor += 1
        elif command == "down" and door_state == "CLOSED":
            if current_floor > min_floor:
                current_floor -= 1
    return (current_floor, door_state)

