def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
    crossing_ticks = []
    for arrival in arrivals:
        # Determine the cycle in which the pedestrian arrives
        cycle = arrival // (red_duration + green_duration)
        # Find the start of the cycle
        cycle_start = cycle * (red_duration + green_duration)
        # Check if the pedestrian arrives during red or green
        if arrival < cycle_start + red_duration:
            # Arrived during red, can cross immediately
            crossing_ticks.append(arrival)
        else:
            # Arrived during green, must wait for next red
            crossing_ticks.append(cycle_start + red_duration + (arrival - cycle_start - red_duration) % (green_duration + red_duration))
    return crossing_ticks

