def classify_triangle_by_sides(p1, p2, p3):
    # Calculate the squared lengths of the sides of the triangle
    a2 = (p2[0] - p1[0])**2 + (p2[1] - p1[1])**2
    b2 = (p3[0] - p2[0])**2 + (p3[1] - p2[1])**2
    c2 = (p1[0] - p3[0])**2 + (p1[1] - p3[1])**2

    # Determine the number of equal sides using squared lengths
    if a2 == b2 == c2:
        return 'equilateral'
    elif a2 == b2 or b2 == c2 or c2 == a2:
        return 'isosceles'
    else:
        return 'scalene'

