        if op == "enter":
            if self.spots[spot_id] is None and self.occupied < capacity:
                self.spots[spot_id] = True
                self.occupied += 1
        elif op == "exit":
            if self.spots[spot_id] is not None:
                self.spots[spot_id] = None
    return sorted([spot for spot, occupied in self.spots.items() if occupied])

